const __contractInputs=$input.all();
const __contractOutput=(()=>{
// ============================================================
// MERGE SCENES + BUILD JOBS
// ============================================================
// Combines:
// 1. Original row data from Loop Over Items
// 2. AI Agent structured scene output
//
// The Agent returns scenes with:
//   type: "text_to_image" | "image_to_video" | "flf_to_video"
//   image_prompt, video_prompt, flf_prompt, dialogue
//
// Scene count from the Agent may differ from the original row's
// scene count — scenes can be split (e.g. SCENE_04 -> SCENE_04A /
// SCENE_04B) or merged (e.g. SCENE_05 + SCENE_06 -> SCENE_05_06)
// to fit the fixed 10-second video job length. This node treats
// the Agent's scene list as authoritative and resolves each
// scene_id back to its original source scene(s) for any fields
// the Agent doesn't return.
//
// This node normalizes type values and builds production jobs,
// including the per-scene image job(s) that must exist before a
// scene's video job can run:
//   text_to_image  -> 1 image job, no video job
//   image_to_video -> 1 image job, then 1 video job
//   flf_to_video   -> 2 image jobs (first frame, last frame),
//                     then 1 video job
// ============================================================


// ------------------------------------------------------------
// 1. GET ORIGINAL ROW DATA
// ------------------------------------------------------------

const rowData = $('Loop Over Items').item.json;

const rowId = rowData.id;
const reffrence = rowData.Reffrence || '';


// ------------------------------------------------------------
// 2. PARSE ORIGINAL SCENES
// ------------------------------------------------------------

let originalScenes;

try {
  originalScenes =
    typeof rowData.Scenes === 'string'
      ? JSON.parse(rowData.Scenes)
      : rowData.Scenes;
} catch (e) {
  throw new Error(
    'Could not parse original Scenes JSON: ' + e.message
  );
}

if (!Array.isArray(originalScenes)) {
  throw new Error('Scenes did not parse to an array');
}

const originalById = {};

for (const s of originalScenes) {
  if (s && s.scene_id !== undefined && s.scene_id !== null) {
    originalById[s.scene_id] = s;
  }
}


// ------------------------------------------------------------
// 3. GET AI AGENT OUTPUT
// ------------------------------------------------------------

const llmOut = $json.output || $json;

const updates = Array.isArray(llmOut.scenes)
  ? llmOut.scenes
  : [];


// ------------------------------------------------------------
// 4. RESOLVE A SCENE_ID BACK TO ITS ORIGINAL SOURCE SCENE(S)
// ------------------------------------------------------------
// Handles three cases:
//   - unchanged: "SCENE_04"        -> originalById["SCENE_04"]
//   - split:     "SCENE_04A"       -> originalById["SCENE_04"]
//   - merged:    "SCENE_05_06"     -> originalById["SCENE_05"],
//                                     originalById["SCENE_06"]

function resolveSourceScenes(sceneId) {

  if (originalById[sceneId]) {
    return [originalById[sceneId]];
  }

  // MERGE: sceneId joins two or more original ids with "_"
  const parts = String(sceneId).split('_');

  for (let i = 1; i < parts.length; i++) {

    const idA = parts.slice(0, i).join('_');
    const idB = parts.slice(i).join('_');

    if (originalById[idA]) {

      if (originalById[idB]) {
        return [originalById[idA], originalById[idB]];
      }

      // idB may be missing the shared prefix
      // (e.g. "06" instead of "SCENE_06")
      const prefixMatch = idA.match(/^(.*?_)(\d+)$/);

      if (prefixMatch) {
        const candidate = prefixMatch[1] + idB;
        if (originalById[candidate]) {
          return [originalById[idA], originalById[candidate]];
        }
      }
    }
  }

  // SPLIT: sceneId is an original id with a trailing letter
  // suffix (A, B, C...)
  const splitMatch = String(sceneId).match(/^(.+?)([A-Za-z])$/);

  if (splitMatch && originalById[splitMatch[1]]) {
    return [originalById[splitMatch[1]]];
  }

  return [];
}


// ------------------------------------------------------------
// 5. NORMALIZE JOB TYPE
// ------------------------------------------------------------

function normalizeType(s) {

  const rawType = s.type || s.Type || '';

  const type = String(rawType)
    .trim()
    .toLowerCase()
    .replace(/[\s-]+/g, '_');

  if (
    type === 'text_to_image' ||
    type === 't2i'
  ) {
    return 'text_to_image';
  }

  if (
    type === 'image_to_video' ||
    type === 'i2v'
  ) {
    return 'image_to_video';
  }

  if (
    type === 'flf_to_video' ||
    type === 'first_last_frame_to_video' ||
    type === 'first/last_frame_to_video'
  ) {
    return 'flf_to_video';
  }

  // Backward compatibility:
  // If an old scene simply says "video",
  // treat it as image_to_video.
  if (type === 'video') {
    return 'image_to_video';
  }

  return '';
}


// ------------------------------------------------------------
// 6. MERGE AGENT OUTPUT + ORIGINAL SCENE DATA
// ------------------------------------------------------------
// The Agent's scene list is authoritative for count and
// scene_id. Any field the Agent doesn't return falls back to
// the resolved original source scene.

const mergedScenes = (updates.length ? updates : originalScenes).map(u => {

  const sources = resolveSourceScenes(u.scene_id);
  const primarySource = sources[0] || {};

  const merged = {

    ...primarySource,
    ...u,

    scene_id: u.scene_id,

    image_prompt:
      u.image_prompt !== undefined
        ? u.image_prompt
        : (primarySource.image_prompt || ''),

    video_prompt:
      u.video_prompt !== undefined
        ? u.video_prompt
        : (primarySource.video_prompt || ''),

    flf_prompt:
      u.flf_prompt !== undefined
        ? u.flf_prompt
        : (primarySource.flf_prompt || ''),

    dialogue:
      u.dialogue !== undefined
        ? u.dialogue
        : (primarySource.dialogue || ''),

    type: normalizeType(u.type !== undefined || u.Type !== undefined ? u : primarySource)

  };

  return merged;

});


// ------------------------------------------------------------
// 7. BUILD PARAMS
// ------------------------------------------------------------

function buildParams(s) {

  const params = {};

  if (
    s.size !== undefined &&
    s.size !== null &&
    s.size !== ''
  ) {
    params.width = s.size;
  }

  if (
    s.height !== undefined &&
    s.height !== null &&
    s.height !== ''
  ) {
    params.height = s.height;
  }

  params.promptEnhance =
    s.enhance_prompt !== undefined
      ? s.enhance_prompt
      : true;

  for (const key of ['seed','negativePrompt','duration','fps']) {
    if (Object.prototype.hasOwnProperty.call(s,key)) params[key]=s[key];
  }
  if (params.seed!==undefined && (!Number.isSafeInteger(params.seed)||params.seed<0)) throw new Error('Invalid scene seed');
  if (params.negativePrompt!==undefined && typeof params.negativePrompt!=='string') throw new Error('Invalid negativePrompt');
  // Scene Production emits second-based timeline ranges (e.g. "5-15").
  // Preserve Scenes timing; Params.duration is generation length, not trim timing.
  if (params.duration !== undefined) {
    const raw = params.duration;
    let seconds = raw;
    if (typeof raw === 'string') {
      const text = raw.trim();
      const scalar = text.match(/^(\d+(?:\.\d+)?)\s*(?:s|sec|seconds)?$/i);
      const range = text.match(/^(\d+(?:\.\d+)?)\s*-\s*(\d+(?:\.\d+)?)$/);
      seconds = scalar ? Number(scalar[1]) : range ? Number(range[2]) - Number(range[1]) : NaN;
    }
    if (typeof seconds !== 'number' || !Number.isFinite(seconds) || seconds <= 0) {
      throw new Error('Invalid duration: row '+rowId+', scene '+s.scene_id+', field duration, raw '+JSON.stringify(raw)+', seconds '+String(seconds)+'; expected positive seconds or increasing start-end seconds');
    }
    params.duration = seconds;
  }
  // AI Agent Rule 4a explicitly requires every generated video clip to be 10s,
  // including split scenes. Never inherit a parent's 15s timeline as render length.
  if (s.type === 'image_to_video' || s.type === 'flf_to_video') params.duration = 10;
  if (params.fps!==undefined && (typeof params.fps!=='number'||!Number.isFinite(params.fps)||params.fps<=0)) throw new Error('Invalid fps: row '+rowId+', scene '+s.scene_id+', field fps, raw '+JSON.stringify(params.fps));
  return params;
}


// ------------------------------------------------------------
// 8. SPLIT AN FLF image_prompt INTO ITS TWO FRAME PROMPTS
// ------------------------------------------------------------
// image_prompt for flf_to_video scenes is formatted as:
//   FIRST FRAME:
//   [...]
//
//   LAST FRAME:
//   [...]

function splitFlfImagePrompt(imagePrompt) {

  const text = String(imagePrompt || '');

  const match = text.match(
    /FIRST FRAME:\s*([\s\S]*?)\s*LAST FRAME:\s*([\s\S]*)/i
  );

  if (match) {
    return {
      firstFrame: match[1].trim(),
      lastFrame: match[2].trim()
    };
  }

  // Fallback: couldn't parse the expected format — use the
  // full text for both so a job still gets created rather than
  // silently dropping the scene's images.
  return {
    firstFrame: text.trim(),
    lastFrame: text.trim()
  };
}


// ------------------------------------------------------------
// 9. BUILD PRODUCTION JOBS
// ------------------------------------------------------------
// Per scene, image job(s) are pushed before that scene's video
// job, so the resulting queue interleaves as:
//   image, video, image, video, image, image, FLF ...

const jobs = [];

for (const s of mergedScenes) {

  const jobType = s.type;
  if (!jobType) throw new Error("Unsupported scene type");
  const params = JSON.stringify({...buildParams(s), scene_id: s.scene_id});

  // ----------------------------------------------------------
  // TEXT TO IMAGE — 1 image, no video job
  // ----------------------------------------------------------

  if (jobType === 'text_to_image') {

    if (s.image_prompt && String(s.image_prompt).trim()) {

      jobs.push({
        type: 'Text to image',
        prompt: String(s.image_prompt).trim(),
        ref: reffrence,
        JobID: rowId,
        SceneID: s.scene_id,
        Working: false,
        Completed: false,
        Params: params
      });

    }

  }


  // ----------------------------------------------------------
  // IMAGE TO VIDEO — 1 image, then 1 video job
  // ----------------------------------------------------------

  if (jobType === 'image_to_video') {

    if (s.image_prompt && String(s.image_prompt).trim()) {

      jobs.push({
        type: 'Text to image',
        prompt: String(s.image_prompt).trim(),
        ref: reffrence,
        JobID: rowId,
        SceneID: s.scene_id + '_IMG',
        Working: false,
        Completed: false,
        Params: params
      });

    }

    if (s.video_prompt && String(s.video_prompt).trim()) {

      jobs.push({
        type: 'Image to video',
        prompt: String(s.video_prompt).trim(),
        ref: reffrence,
        JobID: rowId,
        SceneID: s.scene_id,
        Working: false,
        Completed: false,
        Params: params
      });

    }

  }


  // ----------------------------------------------------------
  // FLF TO VIDEO — 2 images (first + last frame), then 1 video job
  // ----------------------------------------------------------

  if (jobType === 'flf_to_video') {

    if (s.image_prompt && String(s.image_prompt).trim()) {

      const frames = splitFlfImagePrompt(s.image_prompt);

      jobs.push({
        type: 'Text to image',
        prompt: frames.firstFrame,
        ref: reffrence,
        JobID: rowId,
        SceneID: s.scene_id + '_FRAME1',
        Working: false,
        Completed: false,
        Params: params
      });

      jobs.push({
        type: 'Text to image',
        prompt: frames.lastFrame,
        ref: reffrence,
        JobID: rowId,
        SceneID: s.scene_id + '_FRAME2',
        Working: false,
        Completed: false,
        Params: params
      });

    }

    if (s.video_prompt && String(s.video_prompt).trim()) {

      jobs.push({
        type: 'FLF to video',
        prompt: String(s.video_prompt).trim(),
        ref: reffrence,
        JobID: rowId,
        SceneID: s.scene_id,
        Working: false,
        Completed: false,
        Params: params
      });

    }

  }

}


// ------------------------------------------------------------
// 10. RETURN FINAL MERGED DATA
// ------------------------------------------------------------

for (const job of jobs) {
 const p=JSON.parse(job.Params);
 p.frame_role=job.SceneID.endsWith('_FRAME1') ? 'first' : job.SceneID.endsWith('_FRAME2') ? 'last' : job.SceneID.endsWith('_IMG') ? 'source' : 'static';
 job.Params=JSON.stringify(p);
}
return [

  {
    json: {
      rowId: rowId,
      reffrence: reffrence,
      mergedScenesJson: JSON.stringify(mergedScenes),
      jobs: jobs,
      jobCount: jobs.length
    }
  }

];
})();
